document.addEventListener('DOMContentLoaded',()=>{
document.title='EASY CAR WASH — Таны байгаа газарт';document.querySelectorAll('.logo').forEach(x=>{x.firstChild.textContent='EASY';x.querySelector('span').textContent='CAR WASH / ЯВУУЛЫН УГААЛГА'});document.querySelectorAll('.price').forEach(x=>x.innerHTML='Очоод тохирно <small>үнэ</small>');const n=document.createElement('div');n.className='estimate-card';n.innerHTML='<b>🚗 Машины үнэлгээ газар дээр</b><p>Марк, хэмжээ, салон/кузовын байдал, бохирдлын түвшинг үзсэний дараа эцсийн үнийн санал өгнө. Та зөвшөөрсний дараа л угаалга эхэлнэ.</p>';document.querySelector('.booking-note').after(n);document.querySelector('.booking-note p').textContent='Бид очоод машиныг шалгаж, үйлчилгээний хүрээ болон үнийг тантай тохирно.';document.querySelector('.services>.small').textContent='* Тогтсон үнэ байхгүй. Машины хэмжээ, бохирдол, толбо болон очих зайг газар дээр нь үзээд эцсийн үнийг хэлнэ.';document.querySelector('.total').innerHTML='<span>Эцсийн үнэ <small>Машиныг очиж үзсэний дараа тохирно</small></span><strong>Тохирно</strong>';document.querySelector('.submit').innerHTML='Үнийн санал авах цаг захиалах <span>↗</span>';const h=document.querySelector('.dialog-heading h2');if(h)h.textContent='Өнөөдрийн захиалгууд';const i=document.querySelector('#admin .small');if(i)i.textContent='Захиалгыг цагаар нь харж, хийгдсэн / цуцлагдсан төлөвийг нэг товшилтоор шинэчилнэ.';
});
document.addEventListener('DOMContentLoaded',()=>{
  const admin=document.querySelector('#admin'), ordersRoot=document.querySelector('#orders');
  const tools=document.createElement('div'); tools.className='admin-tools'; tools.innerHTML='<div class="admin-summary" id="admin-summary"></div><div class="admin-filter"><input id="admin-search" placeholder="Нэр, утас, улсын дугаараар хайх"><select id="admin-status"><option value="all">Бүх төлөв</option><option value="pending">Хүлээгдэж буй</option><option value="sent">Үнэ санал болгосон</option><option value="accepted">Зөвшөөрсөн</option><option value="done">Хийгдсэн</option><option value="cancelled">Цуцлагдсан</option></select><button id="admin-export">Нөөцлөх</button><label class="admin-import">Сэргээх<input id="admin-import" type="file" accept="application/json"></label></div>';
  ordersRoot.before(tools);
  const refreshSummary=()=>{const all=JSON.parse(localStorage.getItem('nomad-demo-orders-v1')||'[]');const d=document.querySelector('#admin-date').value;const day=all.filter(o=>o.date===d);const accepted=day.filter(o=>o.quoteStatus==='accepted'||o.status==='done');const revenue=accepted.reduce((s,o)=>s+(Number(o.agreedPrice)||0),0);document.querySelector('#admin-summary').textContent=`${d||'Бүх өдөр'} · ${day.length} захиалга · ${accepted.length} баталгаатай · ${revenue.toLocaleString()}₮ тохирсон дүн`};
  document.querySelector('#admin-search').oninput=()=>{const q=document.querySelector('#admin-search').value.toLowerCase();document.querySelectorAll('.order').forEach(x=>x.style.display=x.textContent.toLowerCase().includes(q)?'block':'none')};
  document.querySelector('#admin-status').onchange=()=>{const q=document.querySelector('#admin-status').value;document.querySelectorAll('.order').forEach(x=>{const t=x.textContent.toLowerCase();x.style.display=q==='all'||t.includes(q==='accepted'?'зөвшөөрсөн':q==='sent'?'санал болгосон':q==='cancelled'?'цуцлагдсан':q==='done'?'хийгдсэн':'хүлээгдэж буй')?'block':'none'})};
  document.querySelector('#admin-export').onclick=()=>{const blob=new Blob([localStorage.getItem('nomad-demo-orders-v1')||'[]'],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`easy-car-wash-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href)};
  document.querySelector('#admin-import').onchange=e=>{const file=e.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(reader.result);if(!Array.isArray(data))throw Error();localStorage.setItem('nomad-demo-orders-v1',JSON.stringify(data));window.renderOrders();refreshSummary();alert('Захиалгын нөөц амжилттай сэргээгдлээ.')}catch{alert('JSON файл буруу байна.')}};reader.readAsText(file)};
  const old=window.renderOrders;window.renderOrders=()=>{old();refreshSummary();document.querySelector('#admin-search').value='';document.querySelector('#admin-status').value='all'};
  document.querySelector('#admin-open').addEventListener('click',()=>setTimeout(refreshSummary,50));document.querySelector('#admin-date').addEventListener('change',refreshSummary);
});
(() => {
  const oldRender=window.renderOrders;
  const saveOrders=orders=>localStorage.setItem('nomad-demo-orders-v1',JSON.stringify(orders));
  const enhance=()=>{const orders=JSON.parse(localStorage.getItem('nomad-demo-orders-v1')||'[]').filter(o=>!document.querySelector('#admin-date').value||o.date===document.querySelector('#admin-date').value).sort((a,b)=>Number(a.time)-Number(b.time));document.querySelectorAll('.order').forEach((card,i)=>{const o=orders[i];if(!o||card.querySelector('.quote-tools'))return;const box=document.createElement('div');box.className='quote-tools';box.innerHTML=`<div class="quote-tools-title">Үнэ тохирох</div><div class="quote-row"><input type="number" min="0" step="1000" placeholder="Үнэ ₮" value="${o.agreedPrice||''}"><select><option value="pending">Үнэ хүлээгдэж буй</option><option value="sent">Хэрэглэгчид санал болгосон</option><option value="accepted">Хэрэглэгч зөвшөөрсөн</option><option value="declined">Татгалзсан</option></select><button>Хадгалах</button></div><small>Нэмэлт: ${o.addons||'нэмэлт үйлчилгээ сонгоогүй'}</small>`;const input=box.querySelector('input'),select=box.querySelector('select'),button=box.querySelector('button');select.value=o.quoteStatus||'pending';button.onclick=()=>{const all=JSON.parse(localStorage.getItem('nomad-demo-orders-v1')||'[]');const found=all.find(x=>x.id===o.id);if(found){found.agreedPrice=Number(input.value)||0;found.quoteStatus=select.value;found.quoteUpdatedAt=new Date().toISOString();saveOrders(all);button.textContent='Хадгалагдлаа ✓';setTimeout(()=>{button.textContent='Хадгалах'},1300)}};card.append(box)})};window.renderOrders=()=>{oldRender();enhance()};
  document.querySelector('#admin-open').addEventListener('click',()=>setTimeout(enhance,30));document.querySelector('#admin-date').addEventListener('change',()=>setTimeout(enhance,30));
})();
